/* Study Hub service worker (generated by src/build.py from src/sw_template.js; do not edit sw.js by hand).
   - The page itself: shown from the cache straight away (fast, also offline) while the network copy is fetched
     in the background; when it differs, it is stored and the open pages are told a new version is ready.
   - Icons and the manifest: from the cache.
   - Python (Pyodide, versioned on the CDN) and fonts: cached the first time they are used, so Python also
     works offline after it has run once.
   - Podcasts (audio with range requests), YouTube and the sync API are left to the network. */
const VERSION="12a4ec0809";
const SHELL="studyhub-shell-"+VERSION, RUNTIME="studyhub-runtime-v1";
const SHELL_FILES=["./","./index.html","./manifest.webmanifest","./icons/icon-192.png","./icons/icon-512.png","./icons/maskable-512.png","./icons/apple-touch-icon.png"];

self.addEventListener("install",e=>{
  e.waitUntil(caches.open(SHELL).then(c=>c.addAll(SHELL_FILES)).then(()=>self.skipWaiting()));
});
self.addEventListener("activate",e=>{
  e.waitUntil(caches.keys()
    .then(keys=>Promise.all(keys.filter(k=>k.startsWith("studyhub-shell-")&&k!==SHELL).map(k=>caches.delete(k))))
    .then(()=>self.clients.claim()));
});
self.addEventListener("message",e=>{if(e.data==="version")e.source?.postMessage({type:"version",version:VERSION})});

async function networkFirst(req,key){
  const cache=await caches.open(SHELL);
  try{
    const res=await fetch(req);
    if(res.ok)cache.put(key||req,res.clone());
    return res;
  }catch(err){
    return (await cache.match(key||req,{ignoreSearch:true}))||(await cache.match("./index.html"))||(await cache.match("./"))||Response.error();
  }
}
async function pageFast(e){
  const cache=await caches.open(SHELL),cached=await cache.match("./index.html");
  const update=fetch(e.request,{cache:"no-store"}).then(async res=>{
    if(!res.ok)return res;
    const old=await cache.match("./index.html"),fresh=res.clone();
    const changed=!old||(await old.text())!==(await fresh.clone().text());
    if(changed){
      await cache.put("./index.html",fresh);
      if(old)(await self.clients.matchAll({type:"window"})).forEach(c=>c.postMessage({type:"update"}));
    }
    return res;
  });
  if(cached){e.waitUntil(update.catch(()=>{}));return cached}
  return update.catch(()=>caches.match("./").then(r=>r||Response.error()));
}
async function cacheFirst(req,name){
  const cache=await caches.open(name),hit=await cache.match(req);
  if(hit)return hit;
  const res=await fetch(req);
  if(res.ok||res.type==="opaque")cache.put(req,res.clone());
  return res;
}
async function staleWhileRevalidate(req){
  const cache=await caches.open(RUNTIME),hit=await cache.match(req);
  const net=fetch(req).then(res=>{if(res.ok)cache.put(req,res.clone());return res}).catch(()=>hit);
  return hit||net;
}
self.addEventListener("fetch",e=>{
  const req=e.request;
  if(req.method!=="GET")return;
  const url=new URL(req.url);
  if(url.origin===location.origin){
    if(url.pathname.includes("/podcasts/")||req.headers.has("range"))return;
    if(req.mode==="navigate")return e.respondWith(pageFast(e));
    if(/\/(index\.html)?$/.test(url.pathname))return e.respondWith(networkFirst(req,"./index.html"));
    if(/\/(icons\/|manifest\.webmanifest)/.test(url.pathname))return e.respondWith(cacheFirst(req,SHELL));
    return e.respondWith(networkFirst(req));
  }
  if(url.hostname==="cdn.jsdelivr.net"&&url.pathname.startsWith("/pyodide/"))return e.respondWith(cacheFirst(req,RUNTIME));
  if(url.hostname==="fonts.googleapis.com"||url.hostname==="fonts.gstatic.com")return e.respondWith(staleWhileRevalidate(req));
});
